contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Try withdrawing a given amount from c. If the call does not revert then this contract must be the owner.
    // If it reverts then the balance of c must be unchanged.
    function run(uint withdrawAmount) public payable {
        require(true);

        uint balBefore = address(c).balance;

        bool withdrewReverted;
        // top-level state-changing call attempt
        c.withdraw(withdrawAmount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            withdrewReverted = true;
        } else {
            withdrewReverted = false;
        }

        uint balAfter = address(c).balance;
        address owner = c.owner(); if (__ESBMC_reverted()) return;

        // Exactly one assert combining both cases.
        assert(withdrewReverted ? (balAfter == balBefore) : (owner == address(this)));
    }

    receive() external payable {}
}

